script:
frappe.ui.form.on('Asset Movement', {
    refresh(frm) {
        // Update all existing empty rows when form loads
        if (frm.doc.custom_target_location) {
            update_empty_child_rows(frm);
        }
    },

    custom_target_location: function(frm) {
        // When parent target location changes, update all empty child rows
        if (frm.doc.custom_target_location) {
            update_empty_child_rows(frm);
        }
    }
});

frappe.ui.form.on('Asset Movement Item', {
    // This fires when a new row is added to the table
    form_render: function(frm, cdt, cdn) {
        var child = frappe.get_doc(cdt, cdn);
        if (!child.target_location && frm.doc.custom_target_location) {
            // Direct assignment instead of set_value
            child.target_location = frm.doc.custom_target_location;
            frm.refresh_field('assets');
        }
    },

    // Also handle when asset is set in the row
    asset: function(frm, cdt, cdn) {
        var child = frappe.get_doc(cdt, cdn);
        if (!child.target_location && frm.doc.custom_target_location) {
            // Direct assignment instead of set_value
            child.target_location = frm.doc.custom_target_location;
            frm.refresh_field('assets');
        }
    }
});

function update_empty_child_rows(frm) {
    let updated = false;
    if (frm.doc.assets && frm.doc.assets.length > 0) {
        frm.doc.assets.forEach(function(row) {
            if (!row.target_location && frm.doc.custom_target_location) {
                // Direct assignment instead of set_value
                row.target_location = frm.doc.custom_target_location;
                updated = true;
            }
        });
        if (updated) {
            frm.refresh_field('assets');
        }
    }
}

frappe.ui.form.on("Material Request", {
    refresh(frm) {

        // --- KEEP YOUR ORIGINAL CODE AS IS ---
        setTimeout(() => {
            frm.remove_custom_button("Material Transfer", "Create");
        }, 1000);

        // --- NEW: HIDE MATERIAL TRANSFER (IN TRANSIT) BASED ON ROLE ---
        if (frm.doc.material_request_type === "Material Transfer") {
            const has_ops_manager_role = (frappe.user_roles || []).includes("Operations Manager");

            if (!has_ops_manager_role) {
                setTimeout(() => {
                    frm.remove_custom_button("Material Transfer (In Transit)", "Create");
                    frm.remove_custom_button("Pick List", "Create");
                }, 1000);
            }
        }
    }
});



frappe.ui.form.on("Material Request Item", {

    item_code: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);

        // Only run for Material Transfer
        if (frm.doc.material_request_type !== "Material Transfer") return;

        // Ensure warehouse is selected
        if (!row.from_warehouse && !frm.doc.set_from_warehouse) {
            frappe.msgprint("Please select the Source Warehouse first.");
            return;
        }

        const source_wh = row.from_warehouse || frm.doc.set_from_warehouse;

        frappe.call({
            method: "songa_mobility_customizations.services.rest.get_stock_info",
            args: {
                item_code: row.item_code,
                warehouse: source_wh
            },
            callback(r) {
                if (!r.message) return;

                const data = r.message;

                // Case 1: Stock available
                if (data.available_qty > 0) {
                    frappe.msgprint({
                        title: `Stock Availability for ${row.item_code}`,
                        indicator: "green",
                        message: `
                            <b>Warehouse:</b> ${source_wh}<br>
                            <b>Available Qty:</b> ${data.available_qty}<br>
                            <b>Valuation Rate:</b> ${data.valuation_rate}<br>
                            <b>Total Value:</b> ${data.total_value}
                        `
                    });
                }
                // Case 2: Out of stock → Suggest other warehouses
                else {
                    if (data.other_warehouses && data.other_warehouses.length > 0) {
                        const list = data.other_warehouses
                            .map(w => `<li><b>${w.warehouse}</b> — ${w.actual_qty} qty</li>`)
                            .join("");

                        const warehouse_count = data.other_warehouses.length;
                        const plural = warehouse_count > 1 ? "warehouses" : "warehouse";

                        frappe.msgprint({
                            title: `Item Out of Stock in ${source_wh}`,
                            indicator: "red",
                            message: `
                                <b>${row.item_code}</b> has <b>0 qty</b> in <b>${source_wh}</b>.<br><br>
                                It is available in the following ${plural}:<br><br>
                                <ul style="margin-left: 15px;">${list}</ul>
                                <br>
                                <span style="font-size: 12px; color: gray;">
                                    You may update the warehouse before submitting.
                                </span>
                            `
                        });
                    } else {
                        frappe.msgprint({
                            title: `Item Out of Stock`,
                            indicator: "red",
                            message: `<b>${row.item_code}</b> has <b>0 qty</b> in <b>${source_wh}</b>.<br>No stock available in other warehouses.`
                        });
                    }
                }
            }
        });
    }
});

frappe.ui.form.on('Purchase Order', {
    async before_submit(frm) {
        for (let row of frm.doc.items) {
            const r = await frappe.db.get_value(
                'Item',
                row.item_code,
                'custom_has_attachments'
            );

            if (r && r.custom_has_attachments) {
                // Block submission
                frappe.throw(
                    __('Item "{0}" requires attachments. Please attach the required documents before submitting.', [
                        row.item_code
                    ])
                );
            }
        }
    }
});

frappe.ui.form.on('Landed Cost Voucher', {
    refresh: function(frm) {
        // Add custom button to fetch linked charges
        frm.add_custom_button(__('Fetch All Charges'), function() {
            fetch_linked_charges(frm);
        });
    }
});

function fetch_linked_charges(frm) {
    console.log("Fetch All Charges button clicked");
    console.log("Purchase Receipts table data:", frm.doc.purchase_receipts);

    // Check if purchase receipts are selected
    if (!frm.doc.purchase_receipts || frm.doc.purchase_receipts.length === 0) {
        frappe.msgprint({
            title: __('Warning'),
            indicator: 'orange',
            message: __('Please select at least one Purchase Receipt in the Purchase Receipts table first.')
        });
        return;
    }

    // Filter out empty or null purchase receipts
    const validPurchaseReceipts = frm.doc.purchase_receipts
        .filter(pr => pr.receipt_document)
        .map(pr => pr.receipt_document);

    console.log("Valid Purchase Receipts:", validPurchaseReceipts);

    if (validPurchaseReceipts.length === 0) {
        frappe.msgprint({
            title: __('Warning'),
            indicator: 'orange',
            message: __('Please select at least one valid Purchase Receipt in the Purchase Receipts table first.')
        });
        return;
    }

    frappe.call({
        method: 'songa_mobility_customizations.services.rest.fetch_linked_charges',
        args: {
            'purchase_receipts': validPurchaseReceipts
        },
        callback: function(r) {
            console.log("Server response:", r);
            if (r.message) {
                if (r.message.length === 0) {
                    frappe.msgprint({
                        title: __('No Items Found'),
                        indicator: 'blue',
                        message: __('No linked charges found for the selected Purchase Receipts.')
                    });
                    return;
                }
                update_lcv_taxes(frm, r.message); // Changed to update taxes table
                frappe.show_alert({
                    message: __('Successfully fetched {0} additional charges', [r.message.length]),
                    indicator: 'green'
                });
            }
        },
        error: function(err) {
            console.error("Error fetching linked charges:", err);
            frappe.msgprint({
                title: __('Error'),
                indicator: 'red',
                message: __('Failed to fetch linked charges. Please try again.')
            });
        }
    });
}

function update_lcv_taxes(frm, charges) {
    // Clear existing taxes/charges (optional - you might want to keep existing ones)
    // frm.clear_table('taxes');

    // Add new charges to the Taxes and Charges table
    charges.forEach(charge => {
        let child = frm.add_child('taxes');

        // Map the fields according to Landed Cost Taxes and Charges table structure
        child.expense_account = charge.expense_account;
        child.description = charge.description || charge.item_name || charge.item_code;
        child.amount = charge.amount;

        // Set account currency and exchange rate if needed
        child.account_currency = "KES"; // Default currency, adjust as needed
        child.exchange_rate = 1; // Default exchange rate

        // Optional: Store reference to the source document for tracking
        child.custom_source_receipt = charge.receipt_document;
        child.custom_source_item = charge.purchase_receipt_item;
    });

    // Refresh the taxes table
    frm.refresh_field('taxes');

    // Trigger calculation of totals
    frm.trigger('calculate_totals');
}
